import fs from 'node:fs'
import path from 'node:path'
import { chromium } from 'playwright'

const appOrigin = 'http://127.0.0.1:8099'
const apiOrigin = 'http://172.27.13.11:8080'
const outputDir = path.resolve(process.cwd(), '..', '.task-state', '2334-api-e2e')
fs.mkdirSync(outputDir, { recursive: true })

const state = {
  stage: 'startup',
  createAttempted: false,
  registrationCode: null,
  credentialsReturned: false,
  loginCode: null,
  loginPasswordEncrypted: false,
  loginCredentialsPrefilled: false,
  getInfoCode: null,
  userType: null,
  captchaEnabled: null,
  listInfoCalls: 0,
  saveAreaInfoCalls: 0,
  routerCalls: 0,
  routeError: false,
  errorName: null
}

let browser
let context
let page
let createdPassword = ''
let captchaResponses = []
let finalVideoPath = null

function safeHeaders(headers) {
  const copy = { ...headers }
  delete copy['content-length']
  delete copy['content-encoding']
  delete copy['transfer-encoding']
  return copy
}

function normalizeAnswer(raw) {
  const text = String(raw || '').replace(/```/g, '').trim()
  const equation = text.match(/(\d+)\s*([+\-*/×÷])\s*(\d+)/)
  if (equation) {
    const a = Number(equation[1])
    const b = Number(equation[3])
    const op = equation[2]
    if (op === '+') return String(a + b)
    if (op === '-') return String(a - b)
    if (op === '*' || op === '×') return String(a * b)
    if ((op === '/' || op === '÷') && b !== 0) return String(Math.round(a / b))
  }
  return text.match(/[A-Za-z0-9]+/)?.[0] || ''
}

async function solveCaptcha(imageValue) {
  const source = String(imageValue || '')
  if (!source) throw new Error('captcha-image-missing')
  const dataUrl = source.startsWith('data:image/')
    ? source
    : `data:image/jpeg;base64,${source.replace(/\s+/g, '')}`
  const payload = {
    model: process.env.CAPTCHA_VISION_MODEL || 'auto/deepseek-v4.1-flash',
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: '读取这张登录验证码。若为算术题，只输出计算结果；若为字母数字验证码，原样输出。只输出答案。' },
        { type: 'image_url', image_url: { url: dataUrl } }
      ]
    }],
    max_tokens: 30,
    temperature: 0
  }
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 45000)
  try {
    const response = await fetch(process.env.CAPTCHA_GATEWAY_URL || 'http://127.0.0.1:3425/v1/chat/completions', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.MAGPIE_GATEWAY_KEY || 'magpie'}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload),
      signal: controller.signal
    })
    if (!response.ok) throw new Error('captcha-vision-http-error')
    const result = await response.json()
    const answer = normalizeAnswer(result?.choices?.[0]?.message?.content)
    if (!answer) throw new Error('captcha-answer-empty')
    return answer
  } finally {
    clearTimeout(timer)
  }
}

async function waitUntil(predicate, label, timeoutMs = 20000) {
  const start = Date.now()
  while (Date.now() - start < timeoutMs) {
    const value = await predicate()
    if (value) return value
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  throw new Error(`timeout-${label}`)
}

async function forwardApi(route) {
  const request = route.request()
  const localUrl = new URL(request.url())
  const apiPath = localUrl.pathname.replace(/^\/prod-api/, '') || '/'
  const targetUrl = `${apiOrigin}${apiPath}${localUrl.search}`
  const lowerPath = apiPath.toLowerCase()

  if (lowerPath.includes('/company/info/list')) state.listInfoCalls++
  if (lowerPath.includes('saveareainfo')) state.saveAreaInfoCalls++
  if (lowerPath.includes('getrouters') || lowerPath.includes('generateroutes')) state.routerCalls++

  const upstream = await route.fetch({ url: targetUrl })
  const isCaptcha = request.method() === 'GET' && lowerPath.endsWith('/code')
  const isCreate = request.method() === 'POST' && lowerPath.endsWith('/company/base/createtempaccount')
  const isLogin = request.method() === 'POST' && lowerPath.endsWith('/auth/login')
  const isGetInfo = request.method() === 'GET' && lowerPath.endsWith('/system/user/getinfo')

  if (!isCaptcha && !isCreate && !isLogin && !isGetInfo) {
    await route.fulfill({ response: upstream })
    return
  }

  const bodyText = await upstream.text()
  let body
  try { body = JSON.parse(bodyText) } catch { body = null }

  if (isCaptcha && body) {
    captchaResponses.push(body)
    state.captchaEnabled = body.captchaOnOff === true || body.captchaOnOff === 'true'
    await route.fulfill({
      status: upstream.status(),
      headers: safeHeaders(upstream.headers()),
      body: JSON.stringify({ ...body, img: '' })
    })
    return
  }

  if (isCreate && body) {
    state.registrationCode = Number(body.code)
    createdPassword = String(body.data?.password || '')
    state.credentialsReturned = Boolean(body.data?.userName && createdPassword)
    await route.fulfill({ status: upstream.status(), headers: safeHeaders(upstream.headers()), body: bodyText })
    return
  }

  if (isLogin && body) {
    let loginPayload
    try { loginPayload = request.postDataJSON() } catch { loginPayload = null }
    state.loginPasswordEncrypted = Boolean(createdPassword && loginPayload?.password && loginPayload.password !== createdPassword)
    state.loginCode = Number(body.code)
    await route.fulfill({ status: upstream.status(), headers: safeHeaders(upstream.headers()), body: bodyText })
    return
  }

  if (isGetInfo && body) {
    state.getInfoCode = Number(body.code)
    state.userType = body.user?.userType ?? body.data?.user?.userType ?? body.data?.userType ?? null
    await route.fulfill({ status: upstream.status(), headers: safeHeaders(upstream.headers()), body: bodyText })
    return
  }

  await route.fulfill({ status: upstream.status(), headers: safeHeaders(upstream.headers()), body: bodyText })
}

try {
  browser = await chromium.launch({ headless: true })
  context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: { dir: outputDir, size: { width: 1440, height: 900 } }
  })
  page = await context.newPage()
  await page.addInitScript(() => {
    const css = `
      input, textarea { color: transparent !important; -webkit-text-fill-color: transparent !important; text-shadow: none !important; caret-color: transparent !important; }
      input::placeholder, textarea::placeholder { color: #718096 !important; -webkit-text-fill-color: #718096 !important; }
      [data-testid^="registration-credential-"] { filter: blur(12px) !important; color: transparent !important; -webkit-text-fill-color: transparent !important; }
      img[src^="data:image/"] { filter: blur(24px) !important; }
    `
    const install = () => {
      if (!document.head || document.getElementById('__2334_privacy_mask')) return
      const style = document.createElement('style')
      style.id = '__2334_privacy_mask'
      style.textContent = css
      document.head.appendChild(style)
    }
    install()
    new MutationObserver(install).observe(document, { childList: true, subtree: true })
  })
  await page.route('**/prod-api/**', forwardApi)

  state.stage = 'registration-open'
  await page.goto(`${appOrigin}/register/add`, { waitUntil: 'domcontentloaded', timeout: 20000 })
  const companyTypeButton = page.locator('[data-testid="registration-company-type-01"]')
  await companyTypeButton.waitFor({ state: 'visible', timeout: 15000 })
  await companyTypeButton.click()
  await page.locator('[data-testid="registration-uscc-input"] input').waitFor({ state: 'visible', timeout: 15000 })

  const stamp = new Date().toISOString().replace(/\D/g, '').slice(0, 17)
  const randomTail = String(Math.floor(10000 + Math.random() * 90000))
  const companyName = `T2334-${stamp}`
  const uscc = `91320594T2334${randomTail}`
  const legalName = '测试联调'
  const passportNo = `T2334-${stamp}`

  await page.locator('[data-testid="registration-uscc-input"] input').fill(uscc)
  await page.locator('[data-testid="registration-company-name-input"] input').fill(companyName)
  await page.locator('[data-testid="registration-legal-representative-input"] input').fill(legalName)
  const idType = page.locator('[data-testid="registration-legal-id-type-select"]')
  await idType.locator('input').click()
  await page.locator('.el-select-dropdown__item').filter({ hasText: '护照' }).last().click()
  await page.locator('[data-testid="registration-legal-id-number-input"] input').fill(passportNo)

  state.stage = 'registration-captcha'
  const registrationCaptchaInput = page.locator('[data-testid="registration-captcha-input"] input')
  if (await registrationCaptchaInput.isVisible().catch(() => false)) {
    await waitUntil(() => captchaResponses.length > 0, 'registration-captcha-response')
    const registrationCaptcha = captchaResponses[captchaResponses.length - 1]
    const registrationAnswer = await solveCaptcha(registrationCaptcha.img)
    await registrationCaptchaInput.fill(registrationAnswer)
  }

  state.stage = 'registration-submit'
  state.createAttempted = true
  await page.locator('[data-testid="registration-create-temp-account-button"]').evaluate(element => element.click())
  await page.locator('[data-testid="registration-credentials-dialog"]').waitFor({ state: 'visible', timeout: 30000 })
  if (state.registrationCode !== 200 || !state.credentialsReturned) throw new Error('registration-api-did-not-return-credentials')

  const captchaCountBeforeLogin = captchaResponses.length
  state.stage = 'temporary-login-handoff'
  await page.locator('[data-testid="registration-credentials-login-button"]').evaluate(element => element.click())
  await waitUntil(() => page.url().includes('/login') && page.url().includes('tempAccount=1'), 'login-route')
  const usernameInput = page.locator('[data-testid="login-username-input"] input')
  const passwordInput = page.locator('[data-testid="login-password-input"] input')
  await usernameInput.waitFor({ state: 'visible', timeout: 15000 })
  await passwordInput.waitFor({ state: 'visible', timeout: 15000 })
  state.loginCredentialsPrefilled = Boolean((await usernameInput.inputValue()) && (await passwordInput.inputValue()))

  state.stage = 'login-captcha'
  const loginCaptchaInput = page.locator('.el-form-item[prop="code"] input')
  if (await loginCaptchaInput.isVisible().catch(() => false)) {
    await waitUntil(() => captchaResponses.length > captchaCountBeforeLogin, 'login-captcha-response')
    const loginCaptcha = captchaResponses[captchaResponses.length - 1]
    const loginAnswer = await solveCaptcha(loginCaptcha.img)
    await loginCaptchaInput.fill(loginAnswer)
  }

  state.stage = 'login-submit'
  await page.locator('[data-testid="login-submit-button"]').evaluate(element => element.click())
  await waitUntil(() => state.loginCode !== null, 'login-api-response', 30000)
  if (state.loginCode === 200) await waitUntil(() => state.getInfoCode !== null, 'get-info-response', 20000)
  await page.waitForTimeout(800)

  state.stage = 'cleanup-ephemeral-browser-state'
  await page.evaluate(() => {
    try { localStorage.clear() } catch {}
    try { sessionStorage.clear() } catch {}
  }).catch(() => {})
} catch (error) {
  state.errorName = error?.name || 'Error'
} finally {
  if (page) {
    try {
      const video = page.video()
      if (context) await context.close()
      if (video) finalVideoPath = await video.path()
    } catch {}
  }
  if (browser) await browser.close().catch(() => {})
  const report = {
    stage: state.stage,
    registrationCode: state.registrationCode,
    credentialsReturned: state.credentialsReturned,
    loginCode: state.loginCode,
    loginPasswordEncrypted: state.loginPasswordEncrypted,
    loginCredentialsPrefilled: state.loginCredentialsPrefilled,
    getInfoCode: state.getInfoCode,
    userType: state.userType,
    captchaEnabled: state.captchaEnabled,
    listInfoCalls: state.listInfoCalls,
    saveAreaInfoCalls: state.saveAreaInfoCalls,
    routerCalls: state.routerCalls,
    routeError: state.routeError,
    createAttempted: state.createAttempted,
    errorName: state.errorName,
    videoPath: finalVideoPath
  }
  console.log(JSON.stringify(report))
}
